entries[421224] = { ["name"] = "Overgrown Hochenblume", ["text"] = "5 yd range\n2.5 sec cast\nHochenblume is the most common herb found across the Dragon Isles. It can be found in practically any terrain, growing wherever possible.\n\nSome herbs that grow within the Dream have sentience, and will not take lightly to attempts to gather them. They will uproot and flee from their would-be gatherers, but those who are determined may still be able to gather materials from these creatures." }
entries[421225] = { ["name"] = "Plotting the Course", ["text"] = "Instant 30 min cooldown\nPeriodically release rings for party members to race through.\n\nRings cannot be placed near each other. Cooldown reduced during Feast of Winter Veil." }
entries[421226] = { ["name"] = "Overgrown Saxifrage", ["text"] = "5 yd range\n2.5 sec cast\nSaxifrage is a sturdy herb that can grow in a multitude of places. While generally found in rugged locations like mountains or on cliffs, it can also be found upon the open plains or scarcely within volcanic regions.\n\nSome herbs that grow within the Dream have sentience, and will not take lightly to attempts to gather them. They will uproot and flee from their would-be gatherers, but those who are determined may still be able to gather materials from these creatures." }
entries[421227] = { ["name"] = "Overgrown Writhebark", ["text"] = "5 yd range\n2.5 sec cast\nWrithebark is a verdant herb found on the Dragon Isles. It can be found where there is an abundance of trees or foliage.\n\nSome herbs that grow within the Dream have sentience, and will not take lightly to attempts to gather them. They will uproot and flee from their would-be gatherers, but those who are determined may still be able to gather materials from these creatures." }
